import{_ as i,o as a,c as t,a2 as o}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"03. Industrial & Commercial Applications of Embedded Linux","description":"","frontmatter":{},"headers":[],"relativePath":"03-applications.md","filePath":"03-applications.md"}'),r={name:"03-applications.md"};function s(n,e,l,d,c,p){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="_03-industrial-commercial-applications-of-embedded-linux" tabindex="-1">03. Industrial &amp; Commercial Applications of Embedded Linux <a class="header-anchor" href="#_03-industrial-commercial-applications-of-embedded-linux" aria-label="Permalink to &quot;03. Industrial &amp; Commercial Applications of Embedded Linux&quot;">​</a></h1><p>While hobbyists are familiar with the Raspberry Pi, it is crucial to differentiate between educational prototyping hardware and industrial-grade embedded systems.</p><hr><h2 id="where-embedded-linux-is-deployed" tabindex="-1">Where Embedded Linux is Deployed <a class="header-anchor" href="#where-embedded-linux-is-deployed" aria-label="Permalink to &quot;Where Embedded Linux is Deployed&quot;">​</a></h2><ul><li><strong>Industrial Networking &amp; Infrastructure:</strong> Commercial routers, IoT edge gateways, firewalls, and remote telemetry units (RTUs).</li><li><strong>Aerospace &amp; Defense:</strong> Autonomous vehicle controllers, mission systems, and spaceflight computers (e.g., SpaceX Falcon 9 rocket flight computers run custom Linux kernels).</li><li><strong>Robotics &amp; Automation:</strong> ROS (Robot Operating System) nodes, automated guided vehicles (AGVs), and industrial manipulator arms.</li><li><strong>Consumer Electronics &amp; Point-of-Sale (POS):</strong> Smart appliances, interactive kiosks, digital signage, and medical monitoring equipment.</li></ul><hr><div class="warning custom-block"><p class="custom-block-title">WHY THE RASPBERRY PI IS NOT AN INDUSTRIAL SOLUTION</p><p>The Raspberry Pi is an outstanding educational tool and desktop replacement, but it is rarely used in commercial products due to:</p><ol><li><strong>Software Bloat:</strong> General-purpose Raspberry Pi OS images contain GUI desktop suites, background daemons, and packages that cause slow boot times and high power draw.</li><li><strong>Proprietary GPU Boot Architecture:</strong> Booting relies on closed-source VideoCore GPU binary blobs rather than open standard U-Boot flows.</li><li><strong>Hardware Availability &amp; Cost:</strong> Lack of long-term industrial supply chain guarantees (10+ year availability required for industrial boards).</li></ol><p><strong>Production Approach:</strong> Engineers design around System-on-Modules (SOMs) or reference SBC architectures (e.g., STM32MP1, NXP i.MX8, Microchip SAMA5) running a stripped-down, custom-built Linux distribution.</p></div>',7)])])}const g=i(r,[["render",s]]);export{m as __pageData,g as default};
